  (* [comment removed for export] *)
  Lemma ie_noteq_no_eqv : forall A0 lastn dl,
    ubA = A0 ++ [lastn] -> em !! (lastn - 16) = Some dl ->
    ieq kb (zbytes (el_name dl)) = false -> ¬ has_eqv key_lt key kb S.
  Proof.
    intros A0 lastn dl EA Ldl IEQ. ie_pure.
    eapply (ub_prev_no_eqv key_lt key_lt_SWO key kb S A0 lastn SO EA).
    rewrite key_eqv_ieq. unfold key. rewrite (key_of_node _ _ _ Ldl). exact IEQ.
  Qed.
